<?php require_once '../includes/auth.php'; require_role('admin'); $page_title='Warehouses'; if(isset($_POST['add'])){ $n=clean($conn,$_POST['name']); $l=clean($conn,$_POST['location']); $o=(int)$_POST['owner_id']; $ou=mysqli_fetch_assoc(mysqli_query($conn,"SELECT role FROM users WHERE id=$o")); mysqli_query($conn,"INSERT INTO warehouses(name,location,owner_id,owner_role) VALUES('$n','$l',$o,'{$ou['role']}')"); redirect('warehouses.php'); } include '../includes/header.php'; include '../includes/sidebar.php'; $users=mysqli_query($conn,"SELECT * FROM users"); $q=mysqli_query($conn,"SELECT w.*,u.name owner FROM warehouses w LEFT JOIN users u ON u.id=w.owner_id"); ?>
<div class="row g-4"><div class="col-md-4"><div class="card-box"><h5>Add Warehouse</h5><form method="POST"><input class="form-control mb-2" name="name" placeholder="Warehouse Name"><input class="form-control mb-2" name="location" placeholder="Location"><select class="form-select mb-3" name="owner_id"><?php while($u=mysqli_fetch_assoc($users)){ ?><option value="<?php echo $u['id']; ?>"><?php echo $u['name'].' - '.$u['role']; ?></option><?php } ?></select><button name="add" class="btn btn-success">Save</button></form></div></div><div class="col-md-8"><div class="card-box"><table class="table"><tr><th>Name</th><th>Owner</th><th>Location</th></tr><?php while($r=mysqli_fetch_assoc($q)){ ?><tr><td><?php echo $r['name']; ?></td><td><?php echo $r['owner']; ?></td><td><?php echo $r['location']; ?></td></tr><?php } ?></table></div></div></div><?php include '../includes/footer.php'; ?>
